UPDATE db_erp.t_erp_purchase_form_entry
SET totalpay = (
    SELECT COALESCE(SUM(payprice), 0)
    FROM db_erp.t_erp_purchase_form_payment
    WHERE formentryid = #{entryId}
      AND (auditstatus = 1 OR auditstatus IS NULL)
),
paystatus = CASE
    WHEN orderprice <= (
        SELECT COALESCE(SUM(payprice), 0)
        FROM db_erp.t_erp_purchase_form_payment
        WHERE formentryid = #{entryId}
          AND (auditstatus = 1 OR auditstatus IS NULL)
    ) THEN 2
    WHEN (
        SELECT COALESCE(SUM(payprice), 0)
        FROM db_erp.t_erp_purchase_form_payment
        WHERE formentryid = #{entryId}
          AND (auditstatus = 1 OR auditstatus IS NULL)
    ) > 0 THEN 1
    ELSE 0
END
WHERE id = #{entryId}

UPDATE db_erp.t_erp_fin_account
SET balance = balance - #{payprice}
WHERE id = #{acct}
